import { useState, type FormEvent } from 'react';
import type { EstadoOrcamento, LinhaOrcamento } from '../domain/orcamento';
import { formatarMoeda, parseValor, valorParaCampo } from '../domain/money';
import type { Resultado } from '../domain/types';
import { Botao, CampoTexto, Valor } from './ui';

const ROTULO_ESTADO: Record<EstadoOrcamento, string> = {
  normal: 'Dentro do limite',
  atencao: 'Atenção: perto do limite',
  estourado: 'Estourado',
};

const ICONE_ESTADO: Record<EstadoOrcamento, string> = { normal: '✓', atencao: '!', estourado: '✕' };

const COR_BARRA: Record<EstadoOrcamento, string> = {
  normal: 'bg-emerald-600',
  atencao: 'bg-amber-500',
  estourado: 'bg-red-600',
};

const COR_TEXTO: Record<EstadoOrcamento, string> = {
  normal: 'text-emerald-800',
  atencao: 'text-amber-800',
  estourado: 'text-red-800',
};

interface Props {
  linha: LinhaOrcamento;
  onDefinir: (limite: number) => Resultado<void>;
  onRemover: () => void;
}

export function LinhaOrcamentoItem({ linha, onDefinir, onRemover }: Props) {
  const { categoria, limite, gasto, restante, percentual, estado } = linha;
  const [editando, setEditando] = useState(false);
  const [texto, setTexto] = useState(limite === null ? '' : valorParaCampo(limite));
  const [erro, setErro] = useState<string | undefined>();

  const salvar = (e: FormEvent) => {
    e.preventDefault();
    const valor = parseValor(texto);
    if (valor === null) return setErro('Informe um valor válido, como 500,00.');
    if (valor < 0) return setErro('O limite não pode ser negativo.');
    const r = onDefinir(valor);
    if (!r.ok) return setErro(r.erro);
    setErro(undefined);
    setEditando(false);
  };

  return (
    <li className="py-3" data-testid={`orcamento-${categoria.id}`}>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="min-w-0 font-medium text-slate-900">
          {categoria.nome}
          {categoria.arquivada ? <span className="ml-2 rounded bg-slate-200 px-1.5 py-0.5 text-xs font-normal text-slate-700">arquivada</span> : null}
        </p>
        <div className="flex gap-2">
          <Botao
            variante="secundario"
            aria-label={`${limite === null ? 'Definir limite de' : 'Editar limite de'} ${categoria.nome}`}
            onClick={() => {
              setTexto(limite === null ? '' : valorParaCampo(limite));
              setErro(undefined);
              setEditando(true);
            }}
          >
            {limite === null ? 'Definir limite' : 'Editar limite'}
          </Botao>
          {limite !== null ? (
            <Botao variante="secundario" aria-label={`Remover limite de ${categoria.nome}`} onClick={onRemover}>
              Remover limite
            </Botao>
          ) : null}
        </div>
      </div>

      {editando ? (
        <form onSubmit={salvar} noValidate aria-label={`Limite de ${categoria.nome}`} className="mt-2 flex flex-wrap items-start gap-2">
          <div className="min-w-[10rem] flex-1">
            <CampoTexto label={`Limite mensal de ${categoria.nome}`} value={texto} onChange={(e) => setTexto(e.target.value)} erro={erro} inputMode="decimal" placeholder="0,00" />
          </div>
          <div className="flex gap-2 pt-6">
            <Botao type="submit">Salvar limite</Botao>
            <Botao variante="secundario" onClick={() => setEditando(false)}>
              Cancelar
            </Botao>
          </div>
        </form>
      ) : null}

      {limite === null ? (
        <p className="mt-1 text-sm text-slate-600">
          Sem limite definido · Gasto: <span data-testid="gasto">{formatarMoeda(gasto)}</span>
        </p>
      ) : (
        <div className="mt-2 space-y-1">
          <div
            role="progressbar"
            aria-label={`Consumo do orçamento de ${categoria.nome}`}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.min(percentual ?? (gasto > 0 ? 100 : 0), 100)}
            className="h-2.5 w-full overflow-hidden rounded-full bg-slate-200"
          >
            <div className={`h-full ${COR_BARRA[estado!]}`} style={{ width: `${Math.min(percentual ?? (gasto > 0 ? 100 : 0), 100)}%` }} />
          </div>
          <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-1 text-sm">
            <span className={`font-medium ${COR_TEXTO[estado!]}`} data-testid="estado">
              <span aria-hidden="true">{ICONE_ESTADO[estado!]} </span>
              {ROTULO_ESTADO[estado!]}
              {percentual !== null ? ` · ${percentual}%` : ''}
            </span>
            <span className="text-slate-700">
              Gasto <span data-testid="gasto">{formatarMoeda(gasto)}</span> de <span data-testid="limite">{formatarMoeda(limite)}</span>
            </span>
            <span className="text-slate-700">
              {restante! >= 0 ? 'Restante ' : 'Restante '}
              <Valor centavos={restante!} texto={formatarMoeda(restante!)} data-testid="restante" />
              {restante! < 0 ? (
                <>
                  {' '}
                  · Excedente <span data-testid="excedente">{formatarMoeda(-restante!)}</span>
                </>
              ) : null}
            </span>
          </div>
        </div>
      )}
    </li>
  );
}
import { useState } from 'react';
import { formatarData } from '../domain/date';
import { formatarMoeda, percentual } from '../domain/money';
import {
  acumulado,
  aporteMensalNecessario,
  arquivarMeta,
  editarAporte,
  editarMeta,
  excluirAporte,
  registrarAporte,
  reativarMeta,
  ritmoReal,
  situacaoRitmo,
} from '../domain/metas';
import type { Meta } from '../domain/types';
import { useStore } from '../state/store';
import { AporteForm } from './AporteForm';
import { Alerta, Botao, Cartao, Valor } from './ui';
import { MetaForm } from './MetaForm';

type Modo = 'ver' | 'editar' | 'aportar' | 'historico';

export function MetaCard({ meta, hoje }: { meta: Meta; hoje: string }) {
  const store = useStore();
  const [modo, setModo] = useState<Modo>('ver');
  const [aporteEditandoId, setAporteEditandoId] = useState<string | null>(null);
  const [erro, setErro] = useState<string | null>(null);

  const total = acumulado(meta);
  const pct = percentual(total, meta.valorAlvo);
  const falta = Math.max(meta.valorAlvo - total, 0);
  const necessario = aporteMensalNecessario(meta, hoje);
  const ritmo = situacaoRitmo(meta, hoje);
  const media = ritmoReal(meta, hoje);
  const arquivada = meta.status === 'arquivada';
  const aportesOrdenados = [...meta.aportes].sort((a, b) => (a.data < b.data ? 1 : a.data > b.data ? -1 : 0));

  const textoStatus = {
    ativa: 'Em andamento',
    concluida: meta.concluidaEm ? `Concluída em ${formatarData(meta.concluidaEm)}` : 'Concluída',
    arquivada: 'Arquivada',
  }[meta.status];

  const textoNecessario = (() => {
    switch (necessario.tipo) {
      case 'normal':
        return `Aporte mensal necessário: ${formatarMoeda(necessario.valor)} (${necessario.meses} meses)`;
      case 'ultimo-mes':
        return `Último mês: faltam ${formatarMoeda(necessario.valor)}`;
      case 'vencido':
        return `Prazo vencido: faltam ${formatarMoeda(necessario.valor)}`;
      default:
        return null;
    }
  })();

  const textoRitmo = ritmo
    ? {
        'no-ritmo': `No ritmo (média de ${formatarMoeda(media ?? 0)} por mês nos últimos 3 meses)`,
        'abaixo-do-ritmo': `Abaixo do ritmo (média de ${formatarMoeda(media ?? 0)} por mês nos últimos 3 meses)`,
        'sem-dados': 'Sem dados para estimar o ritmo',
      }[ritmo]
    : null;

  const executar = (op: Parameters<typeof store.aplicar>[0]) => {
    const r = store.aplicar(op);
    setErro(r.ok ? null : r.erro);
    return r;
  };

  return (
    <Cartao className={arquivada ? 'opacity-80' : ''}>
      <article aria-label={`Meta ${meta.nome}`}>
        <div className="flex flex-wrap items-start justify-between gap-2">
          <div className="min-w-0">
            <h2 className="text-lg font-semibold text-slate-900">{meta.nome}</h2>
            <p className="text-sm text-slate-600" data-testid="status">
              {textoStatus}
              {meta.prazo ? ` · Prazo ${formatarData(meta.prazo)}` : ' · Sem prazo'}
            </p>
          </div>
          <p className="text-right text-sm text-slate-700">
            <span className="text-lg font-bold text-slate-900" data-testid="acumulado">{formatarMoeda(total)}</span> de{' '}
            <span data-testid="alvo">{formatarMoeda(meta.valorAlvo)}</span>
          </p>
        </div>

        <div
          role="progressbar"
          aria-label={`Progresso da meta ${meta.nome}`}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.min(pct, 100)}
          className="mt-3 h-3 w-full overflow-hidden rounded-full bg-slate-200"
        >
          <div className={`h-full ${meta.status === 'concluida' ? 'bg-emerald-700' : 'bg-sky-600'}`} style={{ width: `${Math.min(Math.max(pct, 0), 100)}%` }} />
        </div>
        <div className="mt-1 flex flex-wrap justify-between gap-2 text-sm text-slate-700">
          <span data-testid="percentual">{pct}% alcançado</span>
          <span>
            Falta <span data-testid="falta">{formatarMoeda(falta)}</span>
          </span>
        </div>

        {!arquivada && (textoNecessario || textoRitmo) ? (
          <div className="mt-2 space-y-0.5 text-sm text-slate-800">
            {textoNecessario ? <p data-testid="necessario">{textoNecessario}</p> : null}
            {textoRitmo ? <p data-testid="ritmo">{textoRitmo}</p> : null}
          </div>
        ) : null}

        {erro ? (
          <div className="mt-2">
            <Alerta>{erro}</Alerta>
          </div>
        ) : null}

        <div className="mt-3 flex flex-wrap gap-2">
          {!arquivada ? (
            <Botao aria-label={`Registrar lançamento em ${meta.nome}`} onClick={() => setModo(modo === 'aportar' ? 'ver' : 'aportar')}>
              Registrar aporte ou retirada
            </Botao>
          ) : null}
          <Botao variante="secundario" aria-label={`Histórico de ${meta.nome}`} onClick={() => setModo(modo === 'historico' ? 'ver' : 'historico')}>
            Histórico ({meta.aportes.length})
          </Botao>
          <Botao variante="secundario" aria-label={`Editar meta ${meta.nome}`} onClick={() => setModo(modo === 'editar' ? 'ver' : 'editar')}>
            Editar meta
          </Botao>
          {arquivada ? (
            <Botao variante="secundario" aria-label={`Reativar meta ${meta.nome}`} onClick={() => executar((s) => reativarMeta(s, meta.id))}>
              Reativar
            </Botao>
          ) : (
            <Botao variante="secundario" aria-label={`Arquivar meta ${meta.nome}`} onClick={() => executar((s) => arquivarMeta(s, meta.id))}>
              Arquivar
            </Botao>
          )}
        </div>

        {modo === 'editar' ? (
          <div className="mt-3 border-t border-slate-200 pt-3">
            <MetaForm
              inicial={meta}
              onCancelar={() => setModo('ver')}
              onSalvar={(dados) => {
                const r = store.aplicar((s) => editarMeta(s, meta.id, dados, hoje));
                if (r.ok) setModo('ver');
                return r;
              }}
            />
          </div>
        ) : null}

        {modo === 'aportar' ? (
          <div className="mt-3 border-t border-slate-200 pt-3">
            <AporteForm
              rotulo={`Novo lançamento em ${meta.nome}`}
              onCancelar={() => setModo('ver')}
              onSalvar={(dados) => {
                const r = store.aplicar((s) => registrarAporte(s, meta.id, dados));
                if (r.ok) setModo('ver');
                return r;
              }}
            />
          </div>
        ) : null}

        {modo === 'historico' ? (
          <div className="mt-3 border-t border-slate-200 pt-3">
            {aportesOrdenados.length === 0 ? (
              <p className="text-sm text-slate-600">Nenhum lançamento ainda.</p>
            ) : (
              <ul className="divide-y divide-slate-200" aria-label={`Lançamentos de ${meta.nome}`}>
                {aportesOrdenados.map((a) =>
                  aporteEditandoId === a.id ? (
                    <li key={a.id} className="py-3">
                      <AporteForm
                        inicial={a}
                        rotulo={`Editar lançamento de ${formatarData(a.data)}`}
                        onCancelar={() => setAporteEditandoId(null)}
                        onSalvar={(dados) => {
                          const r = store.aplicar((s) => editarAporte(s, meta.id, a.id, dados));
                          if (r.ok) setAporteEditandoId(null);
                          return r;
                        }}
                      />
                    </li>
                  ) : (
                    <li key={a.id} className="flex flex-wrap items-center justify-between gap-2 py-2">
                      <span className="text-sm text-slate-800">
                        {formatarData(a.data)} · {a.valor < 0 ? 'Retirada' : 'Aporte'}
                      </span>
                      <span className="flex flex-wrap items-center gap-2">
                        <Valor centavos={a.valor} texto={formatarMoeda(a.valor)} />
                        <Botao variante="secundario" aria-label={`Editar lançamento de ${formatarData(a.data)}`} onClick={() => setAporteEditandoId(a.id)}>
                          Editar
                        </Botao>
                        <Botao variante="perigo" aria-label={`Excluir lançamento de ${formatarData(a.data)}`} onClick={() => executar((s) => excluirAporte(s, meta.id, a.id))}>
                          Excluir
                        </Botao>
                      </span>
                    </li>
                  ),
                )}
              </ul>
            )}
          </div>
        ) : null}
      </article>
    </Cartao>
  );
}
import { useState, type FormEvent } from 'react';
import { valorParaCampo, parseValor } from '../domain/money';
import { META_NOME_MAX, type DadosMeta } from '../domain/metas';
import type { Meta, Resultado } from '../domain/types';
import { Alerta, Botao, CampoTexto } from './ui';

interface Props {
  inicial?: Meta;
  onSalvar: (dados: DadosMeta) => Resultado<void>;
  onCancelar: () => void;
}

type Erros = Partial<Record<'nome' | 'valorAlvo' | 'prazo' | 'geral', string>>;

export function MetaForm({ inicial, onSalvar, onCancelar }: Props) {
  const [nome, setNome] = useState(inicial?.nome ?? '');
  const [alvo, setAlvo] = useState(inicial ? valorParaCampo(inicial.valorAlvo) : '');
  const [prazo, setPrazo] = useState(inicial?.prazo ?? '');
  const [erros, setErros] = useState<Erros>({});

  const enviar = (e: FormEvent) => {
    e.preventDefault();
    const valorAlvo = parseValor(alvo);
    if (valorAlvo === null) return setErros({ valorAlvo: 'Informe um valor válido, como 5.000,00.' });
    const r = onSalvar({ nome, valorAlvo, prazo: prazo || undefined });
    if (!r.ok) setErros(r.campo ? { [r.campo]: r.erro } : { geral: r.erro });
  };

  return (
    <form onSubmit={enviar} noValidate aria-label={inicial ? 'Editar meta' : 'Nova meta'} className="grid gap-3 sm:grid-cols-3">
      <CampoTexto label="Nome da meta" value={nome} onChange={(e) => setNome(e.target.value)} erro={erros.nome} maxLength={META_NOME_MAX + 20} autoComplete="off" />
      <CampoTexto label="Valor alvo" value={alvo} onChange={(e) => setAlvo(e.target.value)} erro={erros.valorAlvo} inputMode="decimal" placeholder="0,00" />
      <CampoTexto label="Prazo (opcional)" type="date" value={prazo} onChange={(e) => setPrazo(e.target.value)} erro={erros.prazo} />
      {erros.geral ? (
        <div className="sm:col-span-3">
          <Alerta>{erros.geral}</Alerta>
        </div>
      ) : null}
      <div className="flex gap-2 sm:col-span-3">
        <Botao type="submit">{inicial ? 'Salvar meta' : 'Criar meta'}</Botao>
        <Botao variante="secundario" onClick={onCancelar}>
          Cancelar
        </Botao>
      </div>
    </form>
  );
}
import { useState, type FormEvent } from 'react';
import { hojeISO } from '../domain/date';
import { parseValor, valorParaCampo } from '../domain/money';
import type { DadosAporte } from '../domain/metas';
import type { Aporte, Resultado } from '../domain/types';
import { Alerta, Botao, CampoSelect, CampoTexto } from './ui';

interface Props {
  inicial?: Aporte;
  rotulo: string;
  onSalvar: (dados: DadosAporte) => Resultado<void>;
  onCancelar: () => void;
}

type Erros = Partial<Record<'data' | 'valor' | 'geral', string>>;

export function AporteForm({ inicial, rotulo, onSalvar, onCancelar }: Props) {
  const [tipo, setTipo] = useState<'aporte' | 'retirada'>(inicial && inicial.valor < 0 ? 'retirada' : 'aporte');
  const [data, setData] = useState(inicial?.data ?? hojeISO());
  const [valor, setValor] = useState(inicial ? valorParaCampo(Math.abs(inicial.valor)) : '');
  const [erros, setErros] = useState<Erros>({});

  const enviar = (e: FormEvent) => {
    e.preventDefault();
    const centavos = parseValor(valor);
    if (centavos === null || centavos <= 0) return setErros({ valor: 'O valor deve ser maior que zero.' });
    const r = onSalvar({ data, valor: tipo === 'retirada' ? -centavos : centavos });
    if (!r.ok) setErros(r.campo ? { [r.campo]: r.erro } : { geral: r.erro });
  };

  return (
    <form onSubmit={enviar} noValidate aria-label={rotulo} className="grid gap-3 sm:grid-cols-3">
      <CampoSelect label="Tipo de lançamento" value={tipo} onChange={(e) => setTipo(e.target.value as 'aporte' | 'retirada')}>
        <option value="aporte">Aporte</option>
        <option value="retirada">Retirada</option>
      </CampoSelect>
      <CampoTexto label="Data do lançamento" type="date" value={data} onChange={(e) => setData(e.target.value)} erro={erros.data} />
      <CampoTexto label="Valor do lançamento" value={valor} onChange={(e) => setValor(e.target.value)} erro={erros.valor} inputMode="decimal" placeholder="0,00" />
      {erros.geral ? (
        <div className="sm:col-span-3">
          <Alerta>{erros.geral}</Alerta>
        </div>
      ) : null}
      <div className="flex gap-2 sm:col-span-3">
        <Botao type="submit">Salvar lançamento</Botao>
        <Botao variante="secundario" onClick={onCancelar}>
          Cancelar
        </Botao>
      </div>
    </form>
  );
}

