import { FORMATOS_DATA } from '../domain/csv';
import type { FormatoData, MapeamentoCsv } from '../domain/types';
import { CampoSelect } from './ui';

interface Props {
  colunas: string[];
  mapeamento: MapeamentoCsv;
  onChange: (m: MapeamentoCsv) => void;
}

const NENHUMA = '';

export function CsvMapeamento({ colunas, mapeamento, onChange }: Props) {
  const duasColunas = mapeamento.colValor === null;
  const opcoes = colunas.map((nome, i) => (
    <option key={i} value={i}>
      {`Coluna ${i + 1}${nome ? `: ${nome}` : ''}`}
    </option>
  ));
  const numero = (v: string) => (v === NENHUMA ? null : Number(v));
  const atualizar = (parcial: Partial<MapeamentoCsv>) => onChange({ ...mapeamento, ...parcial });

  return (
    <form aria-label="Mapeamento de colunas" onSubmit={(e) => e.preventDefault()} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
      <CampoSelect label="Coluna da data" value={mapeamento.colData} onChange={(e) => atualizar({ colData: Number(e.target.value) })}>
        {opcoes}
      </CampoSelect>
      <CampoSelect label="Coluna da descrição" value={mapeamento.colDescricao} onChange={(e) => atualizar({ colDescricao: Number(e.target.value) })}>
        {opcoes}
      </CampoSelect>
      <CampoSelect label="Formato da data" value={mapeamento.formatoData} onChange={(e) => atualizar({ formatoData: e.target.value as FormatoData })}>
        {FORMATOS_DATA.map((f) => (
          <option key={f} value={f}>
            {f}
          </option>
        ))}
      </CampoSelect>
      <CampoSelect
        label="Como o valor aparece"
        value={duasColunas ? 'duas' : 'uma'}
        onChange={(e) =>
          e.target.value === 'uma'
            ? atualizar({ colValor: mapeamento.colCredito ?? 2, colCredito: null, colDebito: null })
            : atualizar({ colValor: null, colCredito: 2, colDebito: Math.min(3, colunas.length - 1) })
        }
      >
        <option value="uma">Uma coluna, com sinal</option>
        <option value="duas">Colunas separadas de crédito e débito</option>
      </CampoSelect>
      {duasColunas ? (
        <>
          <CampoSelect label="Coluna de crédito" value={mapeamento.colCredito ?? ''} onChange={(e) => atualizar({ colCredito: numero(e.target.value) })}>
            {opcoes}
          </CampoSelect>
          <CampoSelect label="Coluna de débito" value={mapeamento.colDebito ?? ''} onChange={(e) => atualizar({ colDebito: numero(e.target.value) })}>
            {opcoes}
          </CampoSelect>
        </>
      ) : (
        <CampoSelect label="Coluna do valor" value={mapeamento.colValor ?? 0} onChange={(e) => atualizar({ colValor: Number(e.target.value) })}>
          {opcoes}
        </CampoSelect>
      )}
      <label className="flex items-center gap-2 self-end pb-2 text-sm text-slate-800">
        <input
          type="checkbox"
          checked={mapeamento.temCabecalho}
          onChange={(e) => atualizar({ temCabecalho: e.target.checked })}
          className="h-4 w-4 accent-emerald-700"
        />
        A primeira linha é cabeçalho
      </label>
    </form>
  );
}
import { formatarData } from '../domain/date';
import { formatarMoeda } from '../domain/money';
import type { LinhaInterpretada } from '../domain/csv';
import { formatarTags } from '../domain/tags';
import type { Categoria } from '../domain/types';

export interface LinhaPrevia extends LinhaInterpretada {
  duplicata: boolean;
  selecionada: boolean;
  categoriaId?: string;
  /** Tags da regra que casou com a linha. */
  tags: string[];
}

interface Props {
  linhas: LinhaPrevia[];
  categorias: Categoria[];
  onSelecionar: (indice: number, selecionada: boolean) => void;
  onCategoria: (indice: number, categoriaId: string) => void;
}

export function CsvPrevia({ linhas, categorias, onSelecionar, onCategoria }: Props) {
  return (
    <ul className="divide-y divide-slate-200" aria-label="Prévia da importação">
      {linhas.map((l) => {
        const opcoes = categorias.filter((c) => c.tipo === l.tipo && !c.arquivada);
        const estado = l.erro ? `Erro: ${l.erro}` : l.duplicata ? 'Possível duplicata' : 'Pronta';
        const cor = l.erro ? 'text-red-800' : l.duplicata ? 'text-amber-800' : 'text-emerald-800';
        const rotulo = `linha ${l.indice}`;
        return (
          <li key={l.indice} className={`grid gap-2 py-3 sm:grid-cols-[auto_1fr_auto] sm:items-center ${l.erro ? 'bg-red-50' : l.duplicata ? 'bg-amber-50' : ''}`}>
            <input
              type="checkbox"
              aria-label={`Importar ${rotulo}`}
              checked={l.selecionada}
              disabled={Boolean(l.erro)}
              onChange={(e) => onSelecionar(l.indice, e.target.checked)}
              className="h-4 w-4 accent-emerald-700"
            />
            <div className="min-w-0">
              <p className="truncate font-medium text-slate-900">{l.descricao || '(sem descrição)'}</p>
              <p className="text-xs text-slate-600">
                {l.data ? formatarData(l.data) : 'sem data'} · {l.erro ? '—' : `${l.tipo === 'receita' ? 'Receita' : 'Despesa'} ${formatarMoeda(l.valor)}`}
              </p>
              <p className={`text-xs font-medium ${cor}`} data-testid={`estado-linha-${l.indice}`}>
                {estado}
              </p>
              {l.tags.length > 0 ? (
                <p className="text-xs text-slate-600" data-testid={`tags-linha-${l.indice}`}>
                  Tags: {formatarTags(l.tags)}
                </p>
              ) : null}
            </div>
            {!l.erro ? (
              <select
                aria-label={`Categoria da ${rotulo}`}
                value={l.categoriaId ?? ''}
                onChange={(e) => onCategoria(l.indice, e.target.value)}
                className="min-w-0 rounded-md border border-slate-300 bg-white px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-600"
              >
                {opcoes.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.nome}
                  </option>
                ))}
              </select>
            ) : (
              <span />
            )}
          </li>
        );
      })}
    </ul>
  );
}

